-- gen_random_uuid() is built into supported PostgreSQL versions; no extension required.
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='lrt_app') THEN CREATE ROLE lrt_app NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
CREATE FUNCTION lrt_org() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.organization_id',true),'')::uuid $$;
CREATE FUNCTION lrt_subject() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.subject',true),'') $$;
CREATE FUNCTION lrt_system() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.system',true),'')='true' $$;
CREATE FUNCTION lrt_owner() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.owner',true),'')='true' $$;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject text NOT NULL UNIQUE,email text NOT NULL,platform_owner boolean NOT NULL DEFAULT false,disabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members(organization_id uuid NOT NULL REFERENCES organizations,user_id uuid NOT NULL REFERENCES users,role text NOT NULL CHECK(role IN ('org_admin','analyst','client_viewer')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REVOKED')),PRIMARY KEY(organization_id,user_id));
CREATE TABLE plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,max_locations int NOT NULL CHECK(max_locations>0),max_keywords int NOT NULL CHECK(max_keywords>0),max_monthly_queries int NOT NULL CHECK(max_monthly_queries>0),max_users int NOT NULL CHECK(max_users>0),monthly_budget_micros bigint NOT NULL CHECK(monthly_budget_micros>=0));
CREATE TABLE subscriptions(organization_id uuid PRIMARY KEY REFERENCES organizations,plan_id uuid NOT NULL REFERENCES plans,billing_status text NOT NULL CHECK(billing_status IN ('PAID','UNPAID','REVIEW')),entitlement_status text NOT NULL CHECK(entitlement_status IN ('ACTIVE','SUSPENDED')),paid_through timestamptz NOT NULL,version int NOT NULL DEFAULT 1);
CREATE TABLE subscription_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,event_key text NOT NULL,request_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,event_key));
CREATE TABLE brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,name text NOT NULL,UNIQUE(organization_id,id));
CREATE TABLE business_locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,brand_id uuid,name text NOT NULL,city text NOT NULL,address text NOT NULL,maps_url text NOT NULL,cid text,place_id text,lat double precision NOT NULL CHECK(lat BETWEEN -85 AND 85),lng double precision NOT NULL CHECK(lng BETWEEN -180 AND 180),identity_status text NOT NULL DEFAULT 'UNRESOLVED' CHECK(identity_status IN ('UNRESOLVED','CONFIRMED')),source text NOT NULL DEFAULT 'user_entered',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,brand_id) REFERENCES brands(organization_id,id));
CREATE UNIQUE INDEX locations_cid ON business_locations(organization_id,cid) WHERE cid IS NOT NULL;
CREATE UNIQUE INDEX locations_place ON business_locations(organization_id,place_id) WHERE place_id IS NOT NULL;
CREATE TABLE location_acl(organization_id uuid NOT NULL,location_id uuid NOT NULL,user_id uuid NOT NULL,PRIMARY KEY(organization_id,location_id,user_id),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id),FOREIGN KEY(organization_id,user_id) REFERENCES organization_members);
CREATE TABLE keyword_clusters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,name text NOT NULL,normalized_key text NOT NULL,intent text NOT NULL,UNIQUE(organization_id,id),UNIQUE(organization_id,location_id,normalized_key),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id));
CREATE TABLE keywords(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,cluster_id uuid NOT NULL,term text NOT NULL,normalized_key text NOT NULL,kind text NOT NULL CHECK(kind IN ('BRAND','COMMERCIAL')),status text NOT NULL DEFAULT 'SUGGESTED' CHECK(status IN ('SUGGESTED','VALIDATED','ACTIVE','INACTIVE')),priority text NOT NULL,source text NOT NULL DEFAULT 'user_pasted',language text NOT NULL DEFAULT 'pt-BR',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),UNIQUE(organization_id,location_id,normalized_key),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id),FOREIGN KEY(organization_id,cluster_id) REFERENCES keyword_clusters(organization_id,id));
CREATE TABLE search_grids(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,spacing_m int NOT NULL CHECK(spacing_m BETWEEN 50 AND 10000),points jsonb NOT NULL CHECK(jsonb_array_length(points)=25),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id));
CREATE TABLE audit_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,created_by uuid NOT NULL,request_key text NOT NULL,request_hash text NOT NULL,config_snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'QUEUED',provider text NOT NULL,is_demo boolean NOT NULL DEFAULT false,estimated_cost bigint NOT NULL,actual_cost bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,UNIQUE(organization_id,id),UNIQUE(organization_id,request_key),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES organization_members);
CREATE TABLE audit_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,run_id uuid NOT NULL,keyword_id uuid NOT NULL,query_snapshot jsonb NOT NULL,state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','RUNNING','DONE','CANCELLED','UNCERTAIN')),attempts int NOT NULL DEFAULT 0,lease_until timestamptz,idempotency_key text NOT NULL UNIQUE,reserved_cost bigint NOT NULL,UNIQUE(organization_id,id),FOREIGN KEY(organization_id,run_id) REFERENCES audit_runs(organization_id,id),FOREIGN KEY(organization_id,keyword_id) REFERENCES keywords(organization_id,id));
CREATE TABLE rank_measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,run_id uuid NOT NULL,task_id uuid NOT NULL UNIQUE,keyword_id uuid NOT NULL,location_id uuid NOT NULL,query_snapshot jsonb NOT NULL,observed_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('VERIFIED','REVIEW','NO_MATCH_WITHIN_DEPTH','PARTIAL_RESULTS','BLOCKED','ERROR','PROVIDER_UNAVAILABLE','UNSUPPORTED_SURFACE')),position int,result_depth int NOT NULL CHECK(result_depth>=0),identity_match text,provider text NOT NULL,provider_task_ref text NOT NULL,cost bigint NOT NULL CHECK(cost>=0),is_demo boolean NOT NULL DEFAULT false,parser_version text NOT NULL DEFAULT 'v3.1',UNIQUE(organization_id,id),CHECK((status='VERIFIED' AND position>=1 AND position<=result_depth AND identity_match IS NOT NULL) OR (status<>'VERIFIED' AND position IS NULL)),FOREIGN KEY(organization_id,run_id) REFERENCES audit_runs(organization_id,id),FOREIGN KEY(organization_id,task_id) REFERENCES audit_tasks(organization_id,id),FOREIGN KEY(organization_id,keyword_id) REFERENCES keywords(organization_id,id),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id));
CREATE TABLE rank_competitor_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,measurement_id uuid NOT NULL,external_id text NOT NULL,name text NOT NULL,position int NOT NULL,retention_until timestamptz NOT NULL,source text NOT NULL,FOREIGN KEY(organization_id,measurement_id) REFERENCES rank_measurements(organization_id,id));
CREATE TABLE usage_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,task_id uuid NOT NULL UNIQUE,run_id uuid NOT NULL,units int NOT NULL DEFAULT 1,cost bigint NOT NULL DEFAULT 0,reserved_cost bigint NOT NULL,state text NOT NULL DEFAULT 'RESERVED' CHECK(state IN ('RESERVED','SETTLED','RELEASED')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,task_id) REFERENCES audit_tasks(organization_id,id),FOREIGN KEY(organization_id,run_id) REFERENCES audit_runs(organization_id,id));
CREATE TABLE report_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,run_id uuid NOT NULL,content_json jsonb NOT NULL,state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','IN_REVIEW','APPROVED')),approved_by uuid,hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id),FOREIGN KEY(organization_id,run_id) REFERENCES audit_runs(organization_id,id),FOREIGN KEY(organization_id,approved_by) REFERENCES organization_members);
CREATE TABLE audit_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,location_id uuid NOT NULL,created_by uuid NOT NULL,config jsonb NOT NULL,frequency text NOT NULL CHECK(frequency IN ('DAILY','WEEKLY','MONTHLY')),timezone text NOT NULL,enabled boolean NOT NULL DEFAULT true,next_run_at timestamptz NOT NULL,last_error text,version int NOT NULL DEFAULT 1,FOREIGN KEY(organization_id,location_id) REFERENCES business_locations(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES organization_members);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations,actor text NOT NULL,action text NOT NULL,resource_id text,trace_id text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_data_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,requestor uuid NOT NULL REFERENCES users,request_type text NOT NULL,status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_settings(id text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,authorized boolean NOT NULL DEFAULT false,license_tag text,retention_days int NOT NULL DEFAULT 0,global_daily_budget bigint NOT NULL DEFAULT 0,global_monthly_budget bigint NOT NULL DEFAULT 0);
INSERT INTO provider_settings(id) VALUES('disabled');
CREATE FUNCTION reject_rewrite() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only record'; END $$;
CREATE TRIGGER measurements_immutable BEFORE UPDATE OR DELETE ON rank_measurements FOR EACH ROW EXECUTE FUNCTION reject_rewrite();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_rewrite();
CREATE TRIGGER billing_events_immutable BEFORE UPDATE OR DELETE ON subscription_events FOR EACH ROW EXECUTE FUNCTION reject_rewrite();
CREATE TRIGGER grids_immutable BEFORE UPDATE OR DELETE ON search_grids FOR EACH ROW EXECUTE FUNCTION reject_rewrite();
CREATE FUNCTION report_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='APPROVED' OR NEW.content_json<>OLD.content_json OR NEW.hash<>OLD.hash THEN RAISE EXCEPTION 'immutable report snapshot'; END IF; RETURN NEW; END $$;
CREATE TRIGGER report_snapshot_immutable BEFORE UPDATE ON report_drafts FOR EACH ROW EXECUTE FUNCTION report_immutable();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organization_members','subscriptions','subscription_events','brands','business_locations','location_acl','keyword_clusters','keywords','search_grids','audit_runs','audit_tasks','rank_measurements','rank_competitor_observations','usage_ledger','report_drafts','audit_schedules','audit_logs','legal_data_requests'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_scope ON %I USING(organization_id=lrt_org() OR lrt_owner() OR lrt_system()) WITH CHECK(organization_id=lrt_org() OR lrt_owner() OR lrt_system())',t);
END LOOP; END $$;
ALTER TABLE users ENABLE ROW LEVEL SECURITY; ALTER TABLE users FORCE ROW LEVEL SECURITY;
CREATE POLICY users_scope ON users USING(auth_subject=lrt_subject() OR lrt_owner() OR lrt_system()) WITH CHECK(lrt_owner());
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY organizations_scope ON organizations USING(id=lrt_org() OR lrt_owner() OR lrt_system() OR EXISTS(SELECT 1 FROM organization_members m JOIN users u ON u.id=m.user_id WHERE m.organization_id=organizations.id AND u.auth_subject=lrt_subject() AND m.status='ACTIVE')) WITH CHECK(lrt_owner());
CREATE POLICY membership_self ON organization_members FOR SELECT USING(user_id IN (SELECT id FROM users WHERE auth_subject=lrt_subject()));
GRANT USAGE ON SCHEMA public TO lrt_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO lrt_app;
REVOKE INSERT,UPDATE,DELETE ON provider_settings,plans FROM lrt_app;
REVOKE UPDATE,DELETE ON rank_measurements,audit_logs,subscription_events,search_grids FROM lrt_app;
CREATE INDEX tasks_pending ON audit_tasks(state,lease_until);
CREATE INDEX locations_tenant ON business_locations(organization_id);
CREATE INDEX keywords_location ON keywords(organization_id,location_id);
CREATE INDEX measures_history ON rank_measurements(organization_id,location_id,observed_at DESC);
CREATE INDEX usage_period ON usage_ledger(organization_id,created_at);
